export function tourConnections(views,index){const current=views[index];if(!current)return[];if(current.points?.length)return current.points.map(p=>({...p,target:views.findIndex(v=>v.id===p.target)})).filter(p=>p.target>=0&&p.target!==index);const find=test=>views.findIndex(test),exterior=find(v=>v.kind==='sequence'),front=(()=>{const i=find(v=>/delanter/i.test(v.label)&&v.kind==='panorama');return i>=0?i:find(v=>v.kind==='panorama');})(),rear=find(v=>/traser/i.test(v.label)&&v.kind==='panorama'),dashboard=find(v=>/tablero/i.test(v.label)),trunk=find(v=>/maletero/i.test(v.label));let candidates=current.kind==='sequence'?[front,trunk]:index===front?[rear,dashboard,exterior]:index===rear?[front,trunk,exterior]:[front,exterior];let targets=[...new Set(candidates)].filter(i=>i>=0&&i!==index);if(!targets.length&&views.length>1)targets=[(index+1)%views.length];return targets.slice(0,3).map((target,i)=>({target,label:views[target].kind==='sequence'?'Volver al exterior':views[target].label,x:[73,26,50][i],y:[55,58,80][i]}));}
